tools.openseo.estimate_ai_visibility_cost({
  /**
   * @format uuid @pattern ^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$
   */
  projectId: string,
  /** Cadence for the monthly cost estimate. Defaults to the saved schedule, or weekly. */
  scheduleInterval?: "daily" | "weekly" | "monthly",
  /** Optional proposed changes to estimate before saving. */
  patch?: {
    /** @minItems 1 @maxItems 5 */
    engines?: Array<"chatgpt" | "gemini" | "google_ai_overview" | "claude" | "perplexity">,
    /**
     * Country for collection, as a DataForSEO location code from the project market list (2840 = United States). A new tracker defaults to the project's market. Check capabilities for countries an engine cannot use.
     * @integer @exclusiveMinimum 0
     */
    locationCode?: number,
    /**
     * Language for collection. Omit when changing country to use that country's default language.
     * @minLength 2 @maxLength 8
     */
    languageCode?: string,
    /** @maxItems 100 */
    prompts?: Array<{
        /**
         * Existing prompt ID when editing or pausing. Omit for a new prompt. Changing an existing prompt's text archives it and adds the new text as a new prompt, so earlier answers keep their exact prompt.
         * @format uuid @pattern ^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$
         */
        id?: string,
        /**
         * Exact customer prompt or keyword, up to 2,000 characters; casing is preserved. Do not expand or rewrite without the user's direction.
         * @minLength 1 @maxLength 2000
         */
        text: string,
        /**
         * Topic name that groups the prompt. New prompts default to General; edits without a topic keep the saved topic. Set it on an existing prompt to move the prompt; to rename a topic, move every prompt in it.
         * @minLength 1 @maxLength 100
         */
        topic?: string,
        paused?: boolean,
      }>,
    /**
     * @maxItems 100
     * Each item: @format uuid @pattern ^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$
     */
    archivePromptIds?: Array<string>,
  },
  /**
   * @minItems 1 @maxItems 100
   * Each item: @format uuid @pattern ^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$
   */
  promptIds?: Array<string>,
}): Promise<{
  status: "success" | "error",
  data?: {
    /** @integer @minimum 0 */
    promptCount: number,
    /** @integer @minimum 0 */
    engineCount: number,
    /** @integer @minimum 0 */
    observations: number,
    /** @minimum 0 */
    providerCostUsd: number,
    /** @minimum 0 */
    costUsd: number,
    /** @minimum 0 */
    costCredits: number,
    /** @minimum 0 */
    runNowCostUsd: number,
    /** @minimum 0 */
    runNowCostCredits: number,
    scheduleInterval: string,
    /** @integer @minimum 0 */
    checksPerMonth: number,
    /** @minimum 0 */
    monthlyCostUsd: number,
    currency: "USD",
    warnings: Array<string>,
    [key: string]: unknown,
  },
  code?: string,
  message?: string,
  recovery?: string,
  runId?: string,
  meta?: {
    url?: string,
    projectId?: string,
    runId?: string,
    creditsCharged?: number,
    creditsRemaining?: number,
    [key: string]: unknown,
  },
  [key: string]: unknown,
}>

