  [key: string]: unknown,
}>

tools.openseo.find_serp_competitors({
  /** Required. The OpenSEO project ID to scope this call to. Get one from list_projects. @minLength 1 */
  projectId: string,
  /**
   * Keywords whose SERPs are compared (1-100). @minItems 1 @maxItems 100
   * Each item: @minLength 1 @maxLength 120
   */
  keywords: Array<string>,
  /**
   * Legacy US selector. Prefer locationCode/languageCode for any Labs market. Explicit locationCode takes precedence; otherwise omitted = the project's default market.
   */
  market?: {
    /** Country selector. Only the United States can be selected explicitly. */
    country?: "US" | "USA" | "United States" | "United States of America",
  },
  /**
   * Country-level DataForSEO Labs location code. Defaults to the project's market; takes precedence over the legacy market object.
   * @integer @exclusiveMinimum 0
   */
  locationCode?: number,
  /**
   * Language for locationCode. Defaults to that location's primary language when locationCode overrides the project market.
   */
  languageCode?: string,
  /** SERP result types to include. Defaults to organic and local_pack. @minItems 1 @maxItems 4 */
  resultTypes?: Array<"organic" | "paid" | "featured_snippet" | "local_pack">,
  /**
   * Domains to exclude from results (e.g. the user's own site). @minItems 1 @maxItems 50
   * Each item: @minLength 1 @maxLength 255
   */
  excludeDomains?: Array<string>,
  /** Count subdomains as part of the same competitor domain. */
  includeSubdomains?: boolean,
  /** Sort order for returned competitors. Defaults to visibility. */
  sortBy?: "visibility" | "traffic_estimate" | "avg_position" | "keyword_count",
  /** Maximum competitors to return (1-100). Defaults to 50. @integer @minimum 1 @maximum 100 */
  limit?: number,
  /** Rows to skip for pagination. @integer @minimum 0 @maximum 1000 */
  offset?: number,
}): Promise<{
  competitors: Array<{
      [key: string]: unknown,
    }>,
  meta?: {
    url?: string,
    projectId?: string,
    runId?: string,
    creditsCharged?: number,
    creditsRemaining?: number,
    [key: string]: unknown,
  },
  [key: string]: unknown,
}>

